(2292, 'K641901', 'ACTIVIDADES DE RECEPCION DE DEPOSITOS Y/O SIMILARES CERCANOS DE DEPOSITOS Y LA CONCESION DE CREDITOS O PRESTAMOS DE FONDOS. LA CONCESION DE CREDITO PUEDE ADOPTAR DIVERSAS FORMAS, COMO PRESTAMOS, HIPOTECAS, TRANSACCIONES CON TARJETAS DE CREDITO, ETC. ESAS ACTIVIDADES SON REALIZADAS POR BANCOS DIFERENTES DEL BANCO CENTRAL.', '6'),
(2293, 'K641902', 'ACTIVIDADES DE RECEPCION DE DEPOSITOS Y/O SIMILARES CERCANOS DE DEPOSITOS Y LA CONCESION DE CREDITOS O PRESTAMOS DE FONDOS. LA CONCESION DE CREDITO PUEDE ADOPTAR DIVERSAS FORMAS, COMO PRESTAMOS, HIPOTECAS, TRANSACCIONES CON TARJETAS DE CREDITO, ETC. ESAS ACTIVIDADES SON REALIZADAS EN GENERAL POR INSTITUCIONES MONETARIAS DIFERENTES DE LOS BANCOS CENTRALES, COMO: CAJAS DE AHORROS, COOPERATIVAS DE CREDITO Y ACTIVIDADES DE GIRO POSTAL.', '6'),
(2294, 'K641903', 'ACTIVIDADES DE RECEPCION DE DEPOSITOS Y/O SIMILARES CERCANOS DE DEPOSITOS Y LA CONCESION DE CREDITOS O PRESTAMOS DE FONDOS. LA CONCESION DE CREDITO PUEDE ADOPTAR DIVERSAS FORMAS, COMO PRESTAMOS, HIPOTECAS, TRANSACCIONES CON TARJETAS DE CREDITO, ETC. ESAS ACTIVIDADES SON REALIZADAS EN GENERAL POR INSTITUCIONES MONETARIAS DIFERENTES DE LOS BANCOS CENTRALES, COMO; ACTIVIDADES DE CONCESION DE CREDITO PARA COMPRA DE VIVIENDA DE INSTITUCIONES ESPECIALIZADAS QUE RECIBEN DEPOSITOS (MUTUALISTAS).', '6'),
